function escapeHtml(e){return typeof e!="string"?String(e):e.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#x27;")}let webpSupportCache=null;function isWebPSupported(){return webpSupportCache!==null||(webpSupportCache=new Promise(e=>{const r=document.createElement("canvas");r.width=1,r.height=1;try{r.toBlob(l=>{const o=l!==null;logLog(t("log.msg.webpSupported",{result:o?t("log.msg.yes"):t("log.msg.no")})),e(o)},"image/webp")}catch(l){logWarn(t("log.category.browser"),t("log.msg.webpCheckFailed",{msg:l.message||l})),e(!1)}})),webpSupportCache}function clearOverlays(){try{const e=document.querySelectorAll(".processing-overlay");let r=0;return e.forEach(l=>{l&&l.parentNode&&(l.remove(),r++)}),r>0&&logLog(t("log.msg.overlaysCleaned",{n:r})),r}catch(e){return logError(t("log.category.overlay"),t("log.msg.overlayCleanFailed",{msg:e.message||e})),0}}
